/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=activity, operation=get
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Get an activity */
export type PipedriveV2ActivityGetParams = {
  resource: 'activity';
  operation: 'get';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * ID of the activity to get
 * @default 0
 */
    activityId?: number | Expression<number>;
/**
 * Whether to show raw Pipedrive field keys and option IDs instead of human-readable names in output
 * @default false
 */
    rawCustomFieldOutput?: boolean | Expression<boolean>;
};

export type PipedriveV2ActivityGetOutput = {
  add_time?: string;
  busy?: boolean;
  conference_meeting_client?: unknown;
  conference_meeting_id?: unknown;
  conference_meeting_url?: unknown;
  creator_user_id?: number;
  deal_id?: number;
  done?: boolean;
  due_date?: string;
  due_time?: unknown;
  duration?: unknown;
  id?: number;
  is_deleted?: boolean;
  lead_id?: unknown;
  location?: unknown;
  marked_as_done_time?: unknown;
  note?: unknown;
  org_id?: number;
  owner_id?: number;
  participants?: Array<{
    person_id?: number;
    primary?: boolean;
  }>;
  person_id?: number;
  priority?: unknown;
  project_id?: unknown;
  public_description?: unknown;
  subject?: string;
  type?: string;
  update_time?: string;
};

export type PipedriveV2ActivityGetNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  config: NodeConfig<PipedriveV2ActivityGetParams> & { credentials?: Credentials };
  output?: Items<PipedriveV2ActivityGetOutput>;
};